\coordinate (A) at (-1.5,1.5);\coordinate (B) at (-1.5,-1.5);\coordinate (C) at (1.098,0);
\draw (TL)--(TR)--(BR)--(BL)--cycle;\draw (A)--(B)--(C)--cycle;
